// Merge sort — O(n log n) stable, O(n) space
function mergeSort(arr) {
  if (arr.length <= 1) return arr;
  const mid = Math.floor(arr.length / 2);
  const left = mergeSort(arr.slice(0, mid));
  const right = mergeSort(arr.slice(mid));
  return merge(left, right);
}

function merge(left, right) {
  const result = [];
  let i = 0, j = 0;
  while (i < left.length && j < right.length) {
    // '<=' preserves stability: left element wins ties
    if (left[i] <= right[j]) result.push(left[i++]);
    else result.push(right[j++]);
  }
  return result.concat(left.slice(i)).concat(right.slice(j));
}

// Quicksort — O(n log n) avg, O(log n) stack space, unstable
function quickSort(arr, lo = 0, hi = arr.length - 1) {
  if (lo >= hi) return;
  const p = partition(arr, lo, hi);
  quickSort(arr, lo, p - 1);
  quickSort(arr, p + 1, hi);
}

function partition(arr, lo, hi) {
  // Random pivot reduces worst-case probability
  const pivotIdx = lo + Math.floor(Math.random() * (hi - lo + 1));
  [arr[pivotIdx], arr[hi]] = [arr[hi], arr[pivotIdx]];
  const pivot = arr[hi];
  let i = lo - 1;
  for (let j = lo; j < hi; j++) {
    if (arr[j] <= pivot) { i++; [arr[i], arr[j]] = [arr[j], arr[i]]; }
  }
  [arr[i + 1], arr[hi]] = [arr[hi], arr[i + 1]];
  return i + 1;
}

const data = [38, 27, 43, 3, 9, 82, 10];
console.log(mergeSort(data)); // [3, 9, 10, 27, 38, 43, 82]

const data2 = [38, 27, 43, 3, 9, 82, 10];
quickSort(data2);
console.log(data2); // [3, 9, 10, 27, 38, 43, 82]

// ── Complexity & Stability Reference ───────────────────────────
//
// Algorithm      | Best     | Average  | Worst    | Space  | Stable
// ---------------|----------|----------|----------|--------|-------
// Bubble Sort    | O(n)     | O(n²)    | O(n²)    | O(1)   | Yes
// Selection Sort | O(n²)    | O(n²)    | O(n²)    | O(1)   | No
// Insertion Sort | O(n)     | O(n²)    | O(n²)    | O(1)   | Yes
// Merge Sort     | O(n lgn) | O(n lgn) | O(n lgn) | O(n)   | Yes
// Quicksort      | O(n lgn) | O(n lgn) | O(n²)    | O(lgn) | No
// TimSort (JS)   | O(n)     | O(n lgn) | O(n lgn) | O(n)   | Yes

// ── Stability matters when sorting by multiple keys ─────────────
const people = [
  { name: 'Alice', age: 30 },
  { name: 'Bob',   age: 25 },
  { name: 'Carol', age: 30 },
];
// Sort by age — stable sort preserves Alice before Carol (same age)
people.sort((a, b) => a.age - b.age);
// Result: Bob(25), Alice(30), Carol(30)  ← original order among equals preserved

// ── When to use what ───────────────────────────────────────────
// n < 20            → insertion sort (tiny constant, cache friendly)
// stability needed  → merge sort or Array.sort (TimSort)
// in-place, speed   → quicksort with random pivot
// guaranteed O(n lgn) → merge sort or heapsort
